import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Polyline, Popup } from 'react-leaflet';
function App() {
  const [rotas, setRotas] = useState([]);
  useEffect(() => {
    fetch('http://localhost:3001/api/rotas')
      .then(r => r.json()).then(setRotas)
      .catch(() => setRotas([{ id: 1, nome: 'Rua Exemplo', coords: [[-12.97, -38.5], [-12.98, -38.51]], status: 'livre', co2: 0.5 }]));
  }, []);
  return (
    <div style={{ padding: '20px' }}>
      <h1>🌿 Cidades Inteligentes</h1>
      <MapContainer center={[-12.97, -38.51]} zoom={13} style={{ height: '500px', width: '100%' }}>
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
        {rotas.map(rota => (
          <Polyline key={rota.id} positions={rota.coords} color={rota.status === 'congestionado' ? 'red' : 'green'}>
            <Popup>{rota.nome} - CO2: {rota.co2}kg</Popup>
          </Polyline>
        ))}
      </MapContainer>
    </div>
  );
}
export default App;
